window.__medir = (seletor) => new Promise((res) => {
  const a = document.querySelector(seletor);
  if (!a) return res({erro: 'sem link ' + seletor});
  const antes = location.href;
  const main = document.querySelector('main') || document.body;
  let tUrl = null, tDom = null;
  const t0 = performance.now();
  const obs = new MutationObserver(() => { if (tDom === null) tDom = performance.now() - t0; });
  obs.observe(document.body, {childList: true, subtree: true});
  const tick = () => {
    if (tUrl === null && location.href !== antes) tUrl = performance.now() - t0;
    if (tUrl !== null && tDom !== null) { obs.disconnect(); return res({destino: a.getAttribute('href'), urlMs: Math.round(tUrl), domMs: Math.round(tDom)}); }
    if (performance.now() - t0 > 8000) { obs.disconnect(); return res({timeout: true, tUrl, tDom}); }
    requestAnimationFrame(tick);
  };
  a.click();
  requestAnimationFrame(tick);
});
await new Promise(r => setTimeout(r, 2500));
await window.__medir('header a[href="/listas"]')

